<script setup>
import { ref, computed, onMounted } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
// === 移除：导入统一的 API 方法 ===
// import { post as apiPost } from '@/utils/api.js' // 请根据你的实际路径调整

// === 移除：获取 appointmentId ===
// const appointmentId = ref('')
// onLoad((options) => {
//   if (options.appointmentId) {
//     appointmentId.value = options.appointmentId
//   } else {
//     appointmentId.value = 'temp_appointment_001'
//     console.warn('未接收到 appointmentId，使用临时值')
//   }
// })

// 从缓存读取预约表单数据 (新增)
let appointmentFormData = ref({});
onMounted(() => {
  try {
    appointmentFormData.value = uni.getStorageSync('appointmentFormData') || {};
    console.log('【ServiceCompanionSelect】从缓存读取预约表单数据:', appointmentFormData.value);
  } catch (e) {
    console.error('【ServiceCompanionSelect】读取预约表单缓存失败:', e);
  }
});

// 当前选中的服务类型
const selectedServices = ref(['consult', 'exam']) // 默认选中就诊陪同和检查引导

// 切换服务
const toggleService = (type) => {
  if (selectedServices.value.includes(type)) {
    selectedServices.value = selectedServices.value.filter(s => s !== type)
  } else {
    selectedServices.value.push(type)
  }
}

// --- 修改：更新原始数据，将价格改为计算逻辑，并添加价格系数 ---
const rawCompanions = computed(() => {
  // 使用 computed 以便动态计算价格
  // 从缓存获取服务时间计算价格
  const startTime = appointmentFormData.value.startTime;
  const endTime = appointmentFormData.value.endTime;
  let durationHours = 1; // 默认时长
  let baseHourlyRate = 49; // 基础单价 (元/小时)

  if (startTime && endTime) {
    const startMinutes = timeToMinutes(startTime);
    const endMinutes = timeToMinutes(endTime);
    if (endMinutes > startMinutes) {
      durationHours = (endMinutes - startMinutes) / 60;
      console.log('【ServiceCompanionSelect】计算时长:', durationHours, '小时');
    }
  }

  const basePrice = Math.ceil(durationHours * baseHourlyRate); // 计算基础价格
  console.log('【ServiceCompanionSelect】计算基础价格:', basePrice, '元');

  // 定义价格系数
  const priceCoefficients = [1.0, 1.2, 0.8];

  return [
    {
      id: 1,
      name: '王丽',
      avatar: './provider1.jpg',
      rating: 4.8,
      reviews: 126,
      hospital: '北京协和医院内分泌科',
      specialty: '糖尿病患者陪诊经验',
      experience: 5,
      basePrice: basePrice, // 基础价格
      priceCoefficient: priceCoefficients[0], // 价格系数 1.0
      price: Math.ceil(basePrice * priceCoefficients[0]), // 最终价格
      recommended: true,
      qualifications: ['8年临床护理经验', '擅长术后重症专业护理', '能提供康复训练建议', '精通糖尿病患者日常管理', '熟悉北京协和医院就诊流程'],
      services: ['consult', 'exam', 'medication', 'record'],
      reviewSummary: '非常专业的陪诊师，对糖尿病患者的护理很有经验，就诊过程很顺利，详细记录了医生的嘱咐，还提供了很多有用的饮食建议。'
    },
    {
      id: 2,
      name: '张伟',
      avatar: './38da0ad384c9103b9b6de1a987e16191.jpg',
      rating: 4.9,
      reviews: 218,
      hospital: '北京301医院心内科',
      specialty: '心脏病患者陪诊、老年病护理',
      experience: 10,
      basePrice: basePrice, // 基础价格
      priceCoefficient: priceCoefficients[1], // 价格系数 1.2
      price: Math.ceil(basePrice * priceCoefficients[1]), // 最终价格
      recommended: false,
      qualifications: ['10年心血管护理经验', '老年病专科护理认证', '心脏术后康复指导专家', '熟悉各类心脏检查流程', '急救技能认证'],
      services: ['consult', 'exam', 'record', 'rehab'],
      reviewSummary: '张陪诊师非常有耐心，对老年人特别照顾，整个就诊过程安排得很合理，解释病情也很专业，让人非常放心。'
    },
    {
      id: 3,
      name: '刘芳',
      avatar: './1a13f15c8114696a50ebd020c621cc8f.jpg',
      rating: 4.7,
      reviews: 156,
      hospital: '北京儿童医院儿科',
      specialty: '儿童患者陪诊、疫苗接种陪同',
      experience: 7,
      basePrice: basePrice, // 基础价格
      priceCoefficient: priceCoefficients[2], // 价格系数 0.8
      price: Math.ceil(basePrice * priceCoefficients[2]), // 最终价格
      recommended: false,
      qualifications: ['7年儿科护理经验', '儿童心理安抚专家', '熟悉各类疫苗接种流程', '儿童常见疾病护理经验', '儿科检查引导技巧'],
      services: ['consult', 'exam', 'medication', 'diet'],
      reviewSummary: '特别会和孩子沟通，原本害怕看医生的宝宝全程很配合，还详细讲解了注意事项，非常专业的儿科陪诊师。'
    }
  ];
});

// --- 注释：格式化系数显示 ---
// const formatCoefficient = (coef) => {
//   if (coef > 1) {
//     return `+${((coef - 1) * 100).toFixed(0)}%`;
//   } else if (coef < 1) {
//     return `${(coef * 100).toFixed(0)}折`;
//   } else {
//     return '原价';
//   }
// };

// 时间比较工具函数（HH:mm -> 分钟数）
const timeToMinutes = (timeStr) => {
  if (!timeStr) return -1
  const [h, m] = timeStr.split(':').map(Number)
  return h * 60 + m
}

// 排序相关
const sortKey = ref('ai') // 'ai', 'rating', 'price', 'experience'
const priceOrder = ref('desc') // 'asc' 升序, 'desc' 降序

// 计算排序后的列表
const companions = computed(() => {
  let list = [...rawCompanions.value] // 使用计算后的数据
  if (sortKey.value === 'ai') {
    // AI匹配度：推荐的排前面
    list.sort((a, b) => (b.recommended - a.recommended))
  } else if (sortKey.value === 'rating') {
    // 评分：降序（高分在前）
    list.sort((a, b) => b.rating - a.rating)
  } else if (sortKey.value === 'price') {
    // 价格：根据 priceOrder 决定
    if (priceOrder.value === 'asc') {
      list.sort((a, b) => a.price - b.price)
    } else {
      list.sort((a, b) => b.price - a.price)
    }
  } else if (sortKey.value === 'experience') {
    // 经验（用 reviews 代表）：降序
    list.sort((a, b) => b.reviews - a.reviews)
  }
  return list
})

// 设置排序类型
const setSort = (key) => {
  if (key === 'price') {
    togglePriceOrder()
  } else {
    sortKey.value = key
    if (key !== 'price') {
      priceOrder.value = 'desc'
    }
  }
}

// 切换价格排序
const togglePriceOrder = () => {
  sortKey.value = 'price'
  priceOrder.value = priceOrder.value === 'asc' ? 'desc' : 'asc'
}

// 详情弹窗相关
const showDetail = ref(false)
const currentCompanion = ref({})

// 查看详情
const viewDetail = (item) => {
  currentCompanion.value = item
  showDetail.value = true
}

// 关闭详情
const closeDetail = () => {
  showDetail.value = false
}

// --- 修改后的 sendSelectionRequest 函数：移除API调用，直接本地处理 ---
// 构造并处理选择请求 (移除API调用)
const sendSelectionRequest = async (companion) => {
  // 【调试】打印选择的陪诊师对象
  console.log('【调试】用户选择的陪诊师对象:', companion);

  // --- 修改点：将订单确认所需的数据存入缓存 ---
  // 这里将从表单调用、AI匹配（如果有的话）以及当前页面选择的数据合并
  // 以便 OrderConfirmPage 使用
  // 计算金额：时长 * 49元/小时 * 价格系数
  const startMinutes = timeToMinutes(appointmentFormData.value.startTime);
  const endMinutes = timeToMinutes(appointmentFormData.value.endTime);
  let amount = 0;
  if (startMinutes !== -1 && endMinutes !== -1 && endMinutes > startMinutes) {
    const durationHours = (endMinutes - startMinutes) / 60;
    const baseHourlyRate = 49; // 基础单价 (元/小时)
    const finalPricePerHour = baseHourlyRate * companion.priceCoefficient; // 考虑系数后的单价
    amount = Math.ceil(durationHours * finalPricePerHour * 100); // 转为分
  } else {
    // 如果时间无效，使用陪诊师价格 (元转分)
    amount = companion.price * 100;
  }

  // 生成一个模拟的订单号
  const mockOrderNo = `ORD${Date.now()}`;

  const orderConfirmData = {
    // 从缓存获取的表单数据
    ...appointmentFormData.value,
    // 当前页面选择的数据
    attendantId: companion.id,
    attendantName: companion.name,
    // --- 修改点：添加头像信息 ---
    avatarUrl: companion.avatar, // 将选中陪诊师的头像路径存储
    // ---
    attendantPhone: companion.phone || '', // 假设伴诊师对象有电话
    selectedServices: selectedServices.value,
    // 模拟后端返回的数据
    orderNo: mockOrderNo,
    amount: amount, // 使用计算后的金额（分）
    // 临时状态
    payMethod: 'wechat', // 默认支付方式
    remark: '' // 默认备注
  };

  // 修正字段名：将 hospitalName 改为 hospital，将 startTime 改为 serviceTime
  orderConfirmData.hospital = orderConfirmData.hospitalName;
  orderConfirmData.serviceTime = `${orderConfirmData.serviceDate} ${orderConfirmData.startTime}`;
  delete orderConfirmData.hospitalName; // 删除旧字段
  delete orderConfirmData.startTime; // 删除旧字段
  delete orderConfirmData.endTime; // 删除旧字段

  console.log('【调试】准备存储到 orderConfirmData 的数据:', orderConfirmData);
  uni.setStorageSync('orderConfirmData', orderConfirmData);

  // --- 修改点：跳转到订单确认页面 ---
  uni.navigateTo({
    url: '/pages/OrderConfirmPage/OrderConfirmPage'
  });
};

// --- 修改结束 ---

// 从列表选择陪诊师
const selectCompanion = (item) => {
  sendSelectionRequest(item)
}

// 从详情页选择陪诊师
const selectFromDetail = () => {
  closeDetail()
  sendSelectionRequest(currentCompanion.value)
}

// 其他方法
const getImagePath = (fileName) => `/static/${fileName}`
</script>

